(()=>{"use strict";const n=document.createElement("template");n.innerHTML='\n<style>\n\n:host {\n    display: block;\n    width: 100%;\n    height: 100%;\n    font-family: "Segoe UI", sans-serif;\n}\n\n.container {\n    padding: 20px;\n    background: #ffffff;\n    color: #000000;\n    min-height: 100vh;\n    box-sizing: border-box;\n}\n\nh1 {\n    margin: 0 0 20px 0;\n    color: #003B71;\n}\n\n#callCount {\n    margin-bottom: 15px;\n    font-weight: bold;\n    font-size: 16px;\n}\n\n.actionBar {\n    display: flex;\n    gap: 10px;\n    margin-bottom: 20px;\n}\n\n#refreshBtn {\n    background: #003B71;\n    color: white;\n    border: none;\n    padding: 10px 20px;\n    border-radius: 6px;\n    cursor: pointer;\n    font-size: 14px;\n}\n\n#refreshBtn:hover {\n    background: #00264d;\n}\n\n#terminateBtn {\n    background: #C00000;\n    color: white;\n    border: none;\n    padding: 10px 20px;\n    border-radius: 6px;\n    cursor: pointer;\n    font-size: 14px;\n}\n\n#terminateBtn:hover {\n    background: #8a0000;\n}\n\n.callCard {\n    display: flex;\n    align-items: center;\n    gap: 20px;\n    padding: 12px;\n    margin-bottom: 6px;\n    border: 1px solid #cccccc;\n    border-radius: 6px;\n}\n\n.callDetails {\n    display: flex;\n    flex: 1;\n    gap: 40px;\n    align-items: center;\n}\n\n.callField {\n    min-width: 120px;\n\twhite-space: nowrap;\n}\n\n.callField strong {\n    display: block;\n    font-size: 12px;\n    opacity: .7;\n    margin-bottom: 3px;\n}\n\n.callCard strong {\n    display: block;\n    margin-bottom: 4px;\n}\n\n.emptyState {\n    border: 1px dashed #cccccc;\n    border-radius: 8px;\n    padding: 25px;\n    text-align: center;\n    color: #666666;\n}\n\ninput[type="checkbox"] {\n    transform: scale(1.2);\n    margin: 0;\n}\n\n@media (prefers-color-scheme: dark) {\n\n    .container {\n        background: #1e1e1e;\n        color: #ffffff;\n    }\n\n    .callCard {\n        background: #2d2d2d;\n        border-color: #555555;\n    }\n\n    .emptyState {\n        border-color: #555555;\n        color: #cccccc;\n    }\n\n    #refreshBtn {\n        background: #1f4f8c;\n    }\n\n    #terminateBtn {\n        background: #d13438;\n    }\n\n    input[type="checkbox"] {\n        accent-color: #d13438;\n    }\n}\n\n</style>\n\n<div class="container">\n\n    <h1>Contact Terminator</h1>\n\n    <div id="callCount">\n        Active Calls: 0\n    </div>\n\n    <div class="actionBar">\n\n        <button id="refreshBtn">\n            Refresh Contacts\n        </button>\n\n        <button id="terminateBtn">\n            Terminate Selected\n        </button>\n\n    </div>\n\n    <div id="callsContainer">\n\n        <div class="emptyState">\n            No contacts loaded.\n        </div>\n\n    </div>\n\n</div>\n';class e extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.shadowRoot.appendChild(n.content.cloneNode(!0))}connectedCallback(){console.log("CONTACT TERMINATOR STARTED"),this.initializeEvents(),this.renderCalls([{queue:"Reception",ani:"6125551212",waitTime:"00:01:42",interactionId:"ABC123"},{queue:"Customer Service",ani:"9525551000",waitTime:"00:03:18",interactionId:"XYZ789"}])}initializeEvents(){const n=this.shadowRoot.getElementById("refreshBtn"),e=this.shadowRoot.getElementById("terminateBtn");n.addEventListener("click",()=>{console.log("Refresh Contacts clicked")}),e.addEventListener("click",()=>{const n=this.shadowRoot.querySelectorAll(".callCheckbox:checked");console.log("Selected contacts:",n.length)})}renderCalls(n){const e=this.shadowRoot.getElementById("callsContainer");this.shadowRoot.getElementById("callCount").textContent=`Active Calls: ${n.length}`,e.innerHTML="",n.forEach(n=>{const t=document.createElement("div");t.classList.add("callCard"),t.innerHTML=`\n    <input\n        type="checkbox"\n        class="callCheckbox"\n        data-id="${n.interactionId}"\n    >\n\n    <div class="callDetails">\n\n        <div class="callField">\n            <strong>Queue</strong>\n            ${n.queue}\n        </div>\n\n        <div class="callField">\n            <strong>ANI</strong>\n            ${n.ani}\n        </div>\n\n        <div class="callField">\n            <strong>Wait Time</strong>\n            ${n.waitTime}\n        </div>\n\n        <div class="callField">\n            <strong>Interaction ID</strong>\n            ${n.interactionId}\n        </div>\n\n    </div>\n            `,e.appendChild(t)})}}customElements.define("contact-terminator",e)})();